export function onlineLabel(language:UiLanguage,english:string):string {
  return uiText(language,english,labels[english]??english);
}
export function onlineOptions(language:UiLanguage,values:readonly string[]) {
  return values.map(value=>({value,label:onlineLabel(language,value)}));
}
